import { authoriseRead, authoriseToken, authoriseWrite } from './handlers/auth.js'

export const authRouter = createLambdaAuthorizerRouter()

authRouter
  .token({ handler: authoriseToken })
  .request({ method: 'GET', handler: authoriseRead })
